<section ng-controller="tarifHonorController" ng-cloak><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div><article class="card sitara-card"><header class="card-header d-flex justify-content-between align-items-center"><div><h2 class="sitara-card-title">Tarif honor periode aktif</h2><p class="sitara-card-subtitle">Revisi tarif akan membuat versi baru.</p></div><button class="btn btn-sm btn-primary" ng-click="open()" ng-disabled="!activePeriod">Tambah tarif honor</button></header><div class="table-responsive"><table class="table sitara-table mb-0"><thead><tr><th>Prodi</th><th>Kegiatan</th><th>Peran</th><th>Posisi</th><th class="text-end">Bruto</th><th class="text-end">Pajak</th><th>Versi</th><th class="text-end">Aksi</th></tr></thead><tbody><tr ng-repeat="x in datas"><td ng-bind="x.program_code||'Semua prodi'"></td><td ng-bind="x.activity_name"></td><td ng-bind="x.role_type"></td><td ng-bind="x.position_no"></td><td class="text-end table-main" ng-bind="rupiah(x.gross_amount)"></td><td class="text-end" ng-bind="x.tax_rate_percent+'%'"></td><td ng-bind="x.version_no"></td><td><div class="sitara-row-actions justify-content-end"><button class="btn btn-sm btn-outline-primary" ng-click="open(x)">Revisi</button><button class="btn btn-sm btn-outline-danger" ng-click="deactivate(x)">Nonaktifkan</button></div></td></tr><tr ng-if="!datas.length"><td colspan="8" class="sitara-empty">Belum ada tarif honor aktif.</td></tr></tbody></table></div></article>
<div class="modal fade" id="honorRateModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form name="rateForm" ng-submit="save(rateForm)" novalidate><div class="modal-header"><h2 class="modal-title h5">Tarif honor</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Program studi</label><select class="form-select" ng-model="model.study_program_id"><option value="">Semua prodi</option><option ng-repeat="x in programs" ng-value="x.id" ng-bind="x.code+' — '+x.name"></option></select></div><div class="col-md-6"><label class="form-label">Jenis kegiatan</label><select class="form-select" ng-model="model.activity_type_id" required><option value="">Pilih kegiatan</option><option ng-repeat="x in activityTypes" ng-value="x.id" ng-bind="x.code+' — '+x.name"></option></select></div><div class="col-md-4"><label class="form-label">Peran</label><select class="form-select" ng-model="model.role_type" ng-options="x for x in roles"></select></div><div class="col-md-2"><label class="form-label">Posisi</label><input class="form-control" type="number" min="1" max="20" ng-model="model.position_no" required></div><div class="col-md-3"><label class="form-label">Bruto</label><input class="form-control" type="number" min="1" ng-model="model.gross_amount" required></div><div class="col-md-3"><label class="form-label">Pajak (%)</label><input class="form-control" type="number" min="0" max="100" step="0.01" ng-model="model.tax_rate_percent" required></div><div class="col-12"><label class="form-label">Catatan</label><textarea class="form-control" ng-model="model.notes"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-outline-gray" type="button" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary" type="submit">Simpan tarif</button></div></form></div></div></div></section>
